// reveal.js ships no type declarations. Kept in its own script (non-module)
// file so these are ambient declarations rather than module augmentations.
declare module 'reveal.js';
declare module 'reveal.js/plugin/highlight/highlight';
declare module 'reveal.js/plugin/notes/notes';
declare module 'reveal.js/plugin/math/math';
declare module 'reveal.js/plugin/math/math.js';
declare module 'reveal.js/plugin/markdown/markdown.js';
